import "stonfi_swap_types"

contract StonFiSwap {
    author: "OpenAI"
    version: "0.1.0"
    description: "STON.fi swap POC contract"
    storage: Storage
    incomingMessages: AllowedMessage
}

type AllowedMessage =
    | UpdateRoutePreset
    | ExecuteSimpleSwapWithReferral
    | ExecuteCrossSwapSameRouter
    | ExecuteCrossSwapDifferentRouters
    | ExecuteRefundSwap

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessage.fromSlice(in.body);

    match (msg) {
        UpdateRoutePreset => {
            handleUpdateRoutePreset(in.senderAddress, msg);
        }
        ExecuteSimpleSwapWithReferral => {
            handleSimpleSwapWithReferral(in.senderAddress, msg);
        }
        ExecuteCrossSwapSameRouter => {
            handleCrossSwapSameRouter(in.senderAddress, msg);
        }
        ExecuteCrossSwapDifferentRouters => {
            handleCrossSwapDifferentRouters(in.senderAddress, msg);
        }
        ExecuteRefundSwap => {
            handleRefundSwap(in.senderAddress, msg);
        }
        else => {
            assert (in.body.isEmpty()) throw Errors.InvalidMessage;
        }
    }
}

fun handleUpdateRoutePreset(senderAddress: address, msg: UpdateRoutePreset) {
    val storage = lazy Storage.load();
    assert (storage.owner == senderAddress) throw Errors.NotOwner;
    msg.routePreset.validate();

    var updatedStorage = storage;
    updatedStorage.routePreset = msg.routePreset;
    updatedStorage.save();
}

fun handleSimpleSwapWithReferral(senderAddress: address, msg: ExecuteSimpleSwapWithReferral) {
    val storage = lazy Storage.load();
    assert (storage.owner == senderAddress) throw Errors.NotOwner;
    assert (msg.amount > 0) throw Errors.InvalidSwapConfig;
    assert (msg.forwardTonAmount > 0) throw Errors.InvalidForwardTonAmount;
    val swapPlan = msg.swapPlan.load();
    swapPlan.validateForSimpleSwapWithReferral();

    val transfer = buildJettonTransfer(
        swapPlan.excessesAddress,
        msg.queryId,
        msg.amount,
        msg.routerWalletAddress,
        msg.forwardTonAmount,
        buildStonFiSwapPayload(swapPlan),
    );
    sendJettonTransfer(msg.sourceWalletAddress, transfer);
}

fun handleCrossSwapSameRouter(senderAddress: address, msg: ExecuteCrossSwapSameRouter) {
    val storage = lazy Storage.load();
    assert (storage.owner == senderAddress) throw Errors.NotOwner;
    assert (msg.amount > 0) throw Errors.InvalidSwapConfig;
    assert (msg.forwardTonAmount > 0) throw Errors.InvalidForwardTonAmount;
    val firstPlan = msg.firstPlan.load();
    val secondPlan = msg.secondPlan.load();
    firstPlan.validateForCrossSwapFirstLeg();
    secondPlan.validateForSwap();

    val crossPayload = buildStonFiCrossSwapPayload(secondPlan).toCell();
    val firstPayload = buildStonFiSwapPayload(firstPlan, crossPayload);
    val transfer = buildJettonTransfer(
        firstPlan.excessesAddress,
        msg.queryId,
        msg.amount,
        msg.routerWalletAddress,
        msg.forwardTonAmount,
        firstPayload,
    );
    sendJettonTransfer(msg.sourceWalletAddress, transfer);
}

fun handleCrossSwapDifferentRouters(senderAddress: address, msg: ExecuteCrossSwapDifferentRouters) {
    val storage = lazy Storage.load();
    assert (storage.owner == senderAddress) throw Errors.NotOwner;
    assert (msg.amount > 0) throw Errors.InvalidSwapConfig;
    assert (msg.forwardTonAmount > 0) throw Errors.InvalidForwardTonAmount;
    val firstPlan = msg.firstPlan.load();
    val secondPlan = msg.secondPlan.load();
    firstPlan.validateForCrossSwapFirstLeg();
    secondPlan.validateForSwap();

    val multiRouterPayload = buildStonFiMultiRouterSwapPayload(firstPlan, secondPlan);
    val transfer = buildJettonTransfer(
        firstPlan.excessesAddress,
        msg.queryId,
        msg.amount,
        msg.routerWalletAddress,
        msg.forwardTonAmount,
        multiRouterPayload,
    );
    sendJettonTransfer(msg.sourceWalletAddress, transfer);
}

fun handleRefundSwap(senderAddress: address, msg: ExecuteRefundSwap) {
    val storage = lazy Storage.load();
    assert (storage.owner == senderAddress) throw Errors.NotOwner;
    assert (msg.amount > 0) throw Errors.InvalidSwapConfig;
    assert (msg.forwardTonAmount > 0) throw Errors.InvalidForwardTonAmount;
    val swapPlan = msg.swapPlan.load();
    swapPlan.validateForRefundSwap();

    val transfer = buildJettonTransfer(
        swapPlan.excessesAddress,
        msg.queryId,
        msg.amount,
        msg.routerWalletAddress,
        msg.forwardTonAmount,
        buildStonFiSwapPayload(swapPlan),
    );
    sendJettonTransfer(msg.sourceWalletAddress, transfer);
}

fun buildJettonTransfer(
    responseDestination: address,
    queryId: uint64,
    amount: coins,
    destination: address,
    forwardTonAmount: coins,
    swapPayload: StonFiSwapPayload,
): JettonTransfer {
    return JettonTransfer {
        queryId,
        amount,
        destination,
        responseDestination,
        customPayload: null,
        forwardTonAmount,
        forwardPayload: StonFiTlbEither.right(
            swapPayload.toCell() as cell as Cell<RemainingBitsAndRefs>,
        ),
    };
}

fun sendJettonTransfer(sourceWalletAddress: address, transfer: JettonTransfer) {
    val transferMessage = createMessage({
        bounce: true,
        value: ton("0"),
        dest: sourceWalletAddress,
        body: transfer,
    });

    transferMessage.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
}

fun onBouncedMessage(_in: InMessageBounced) {}

get fun routePreset(): RoutePreset? {
    val storage = lazy Storage.load();

    return storage.routePreset;
}

get fun owner(): address {
    val storage = lazy Storage.load();

    return storage.owner;
}

type StonFiTlbEither<X, Y> = StonFiTlbEitherLeft<X> | StonFiTlbEitherRight<Y>

@inline
fun StonFiTlbEither<X, Y>.left(value: X): StonFiTlbEitherLeft<X> {
    return StonFiTlbEitherLeft { value };
}

@inline
fun StonFiTlbEither<X, Y>.right(value: Y): StonFiTlbEitherRight<Y> {
    return StonFiTlbEitherRight { value };
}

struct (0b0) StonFiTlbEitherLeft<X> {
    value: X
}

struct (0b1) StonFiTlbEitherRight<X> {
    value: X
}

enum Errors {
    NotOwner = 100
    InvalidSwapConfig = 0x1001
    InvalidReferralFee = 0x1002
    InvalidForwardTonAmount = 0x1003
    InvalidRoutePreset = 0x1004
    InvalidMessage = 0xFFFF
}

struct RoutePresetRoutes {
    sourceWalletAddress: address
    routerWalletAddress: address
    firstHopReceiverAddress: address
}

struct RoutePresetTokens {
    tokenWallet1Address: address
}

struct RoutePresetTargets {
    secondRouterWalletAddress: address
    receiverAddress: address
    referrerAddress: address
}

struct RoutePresetFees {
    refundAddress: address
    excessesAddress: address
    fwdGas: coins
    refundFwdGas: coins
}

struct RoutePreset {
    routes: Cell<RoutePresetRoutes>
    tokens: Cell<RoutePresetTokens>
    targets: Cell<RoutePresetTargets>
    fees: Cell<RoutePresetFees>
}

struct Storage {
    id: uint32
    owner: address
    routePreset: RoutePreset?
}

fun Storage.load(): Storage {
    return Storage.fromCell(contract.getData());
}

fun Storage.save(self) {
    contract.setData(self.toCell());
}

fun RoutePreset.loadRoutes(self): RoutePresetRoutes {
    return self.routes.load();
}

fun RoutePreset.loadTokens(self): RoutePresetTokens {
    return self.tokens.load();
}

fun RoutePreset.loadTargets(self): RoutePresetTargets {
    return self.targets.load();
}

fun RoutePreset.loadFees(self): RoutePresetFees {
    return self.fees.load();
}

fun RoutePreset.validate(self): void {
    val fees = self.loadFees();
    assert (fees.fwdGas > 0) throw Errors.InvalidRoutePreset;
    assert (fees.refundFwdGas > 0) throw Errors.InvalidRoutePreset;
}

fun unwrapRoutePreset(value: RoutePreset?): RoutePreset {
    if (value == null) {
        throw Errors.InvalidRoutePreset;
    }

    return value;
}

struct SwapRouteBody {
    minOut: coins
    receiver: address
    fwdGas: coins
    customPayload: cell?
    refundFwdGas: coins
    refundPayload: cell?
    refFee: uint16
    refAddress: address
}

fun SwapRouteBody.withCustomPayload(self, customPayload: cell?): SwapRouteBody {
    return SwapRouteBody {
        minOut: self.minOut,
        receiver: self.receiver,
        fwdGas: self.fwdGas,
        customPayload,
        refundFwdGas: self.refundFwdGas,
        refundPayload: self.refundPayload,
        refFee: self.refFee,
        refAddress: self.refAddress,
    };
}

struct SwapPlan {
    tokenWallet1: address
    refundAddress: address
    excessesAddress: address
    txDeadline: uint64
    routeBody: Cell<SwapRouteBody>
}

fun SwapPlan.validateForSwap(self): void {
    val routeBody = self.routeBody.load();
    assert (routeBody.customPayload == null) throw Errors.InvalidSwapConfig;
    assert (routeBody.refFee <= 100) throw Errors.InvalidReferralFee;
}

fun SwapPlan.validateForSimpleSwapWithReferral(self): void {
    self.validateForSwap();
    assert (self.routeBody.load().refFee > 0) throw Errors.InvalidReferralFee;
}

fun SwapPlan.validateForRefundSwap(self): void {
    self.validateForSwap();
    assert (self.routeBody.load().refFee == 0) throw Errors.InvalidReferralFee;
}

fun SwapPlan.validateForCrossSwapFirstLeg(self): void {
    self.validateForSwap();
    assert (self.routeBody.load().fwdGas > 0) throw Errors.InvalidForwardTonAmount;
}

struct (0x6664de2a) StonFiSwapPayload {
    tokenWallet1: address
    refundAddress: address
    excessesAddress: address
    txDeadline: uint64
    routeBody: Cell<SwapRouteBody>
}

struct (0x69cf1a5b) StonFiCrossSwapPayload {
    tokenWallet1: address
    refundAddress: address
    excessesAddress: address
    txDeadline: uint64
    routeBody: Cell<SwapRouteBody>
}

fun buildStonFiSwapPayload(plan: SwapPlan, customPayload: cell? = null): StonFiSwapPayload {
    val routeBody = plan.routeBody.load();
    return StonFiSwapPayload {
        tokenWallet1: plan.tokenWallet1,
        refundAddress: plan.refundAddress,
        excessesAddress: plan.excessesAddress,
        txDeadline: plan.txDeadline,
        routeBody: routeBody.withCustomPayload(customPayload).toCell(),
    };
}

fun buildStonFiCrossSwapPayload(plan: SwapPlan): StonFiCrossSwapPayload {
    return StonFiCrossSwapPayload {
        tokenWallet1: plan.tokenWallet1,
        refundAddress: plan.refundAddress,
        excessesAddress: plan.excessesAddress,
        txDeadline: plan.txDeadline,
        routeBody: plan.routeBody,
    };
}

fun buildStonFiMultiRouterSwapPayload(
    firstPlan: SwapPlan,
    secondPlan: SwapPlan,
): StonFiSwapPayload {
    return buildStonFiSwapPayload(firstPlan, buildStonFiSwapPayload(secondPlan).toCell());
}

struct (0x0f8a7ea5) JettonTransfer {
    queryId: uint64
    amount: coins
    destination: address
    responseDestination: address
    customPayload: cell?
    forwardTonAmount: coins
    forwardPayload: StonFiTlbEither<RemainingBitsAndRefs, Cell<RemainingBitsAndRefs>>
}

struct (0x5f5a0001) ExecuteSimpleSwapWithReferral {
    queryId: uint64
    sourceWalletAddress: address
    routerWalletAddress: address
    amount: coins
    forwardTonAmount: coins
    swapPlan: Cell<SwapPlan>
}

struct (0x5f5a0002) ExecuteCrossSwapSameRouter {
    queryId: uint64
    sourceWalletAddress: address
    routerWalletAddress: address
    amount: coins
    forwardTonAmount: coins
    firstPlan: Cell<SwapPlan>
    secondPlan: Cell<SwapPlan>
}

struct (0x5f5a0003) ExecuteRefundSwap {
    queryId: uint64
    sourceWalletAddress: address
    routerWalletAddress: address
    amount: coins
    forwardTonAmount: coins
    swapPlan: Cell<SwapPlan>
}

struct (0x5f5a0004) UpdateRoutePreset {
    routePreset: RoutePreset
}

struct (0x5f5a0005) ExecuteCrossSwapDifferentRouters {
    queryId: uint64
    sourceWalletAddress: address
    routerWalletAddress: address
    amount: coins
    forwardTonAmount: coins
    firstPlan: Cell<SwapPlan>
    secondPlan: Cell<SwapPlan>
}
